/* * @lc app=leetcode id=1004 lang=kotlin * * [1004] Max Consecutive Ones III */ class Solution { fun longestOnes(nums: IntArray, k: Int): Int = nums.fold(0 to 0) { (l, z), n -> (z + if (n == 0) 1 else 0).let { nz -> if (nz > k) (l + 1) to (nz - if (nums[l] == 0) 1 else 0) else l to nz } }.let { (l, _) -> nums.size - l } }